tail='''function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  const {limit, before} = message;

  if (limit !== undefined && !isValidLimit(limit)) {
    return fail('list_sessions limit must be a non-negative integer');
  }

  const listed: ListSessionsMessage = {type: 'list_sessions'};
  if (limit !== undefined) {
    listed.limit = limit as number;
  }

  if (before === undefined) {
    return {valid: true, data: listed};
  }

  const cursor = validateCursor(before);
  if ('valid' in cursor) {
    return cursor;
  }
  listed.before = cursor;
  return {valid: true, data: listed};
}

function validateCursor(before: unknown): ValidationFailure | NonNullable<ListSessionsMessage['before']> {
  if (typeof before !== 'object' || before === null) {
    return fail('list_sessions before must be an object');
  }
  const {updatedAt, sessionId} = before as Record<string, unknown>;
  if (!isValidSessionId(sessionId)) {
    return fail(`list_sessions before.sessionId must be 1-${MAX_SESSION_ID_LENGTH} characters`);
  }
  if (!isValidUpdatedAt(updatedAt)) {
    return fail('list_sessions before.updatedAt must be a date string or number');
  }
  return {updatedAt, sessionId};
}

function isValidLimit(limit: unknown): limit is number {
  return typeof limit === 'number' && Number.isInteger(limit) && limit >= 0;
}

function isValidSessionId(sessionId: unknown): sessionId is string {
  return typeof sessionId === 'string' && sessionId.length >= 1 && sessionId.length <= MAX_SESSION_ID_LENGTH;
}

function isValidUpdatedAt(updatedAt: unknown): updatedAt is string | number {
  return (
    (typeof updatedAt === 'string' || typeof updatedAt === 'number') && Number.isFinite(new Date(updatedAt).getTime())
  );
}
'''
